const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;
// TH15 source type18: existing modern large-ball slot (shared radius mapping).
const TH15_BIG_BALL: int = 640;

sub death_shot() {
    // st06:1071-1097: mode1, N=1, M=1/3/5/7; fixed downward layers.
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var top: fx = 2fx;
    if rank == 1 { layers = 3; top = 4fx; }
    if rank == 2 { layers = 5; top = 5fx; }
    if rank == 3 { layers = 7; top = 6fx; }
    for q in 0..layers {
        var speed: fx = top;
        if layers > 1 { speed = top + (1fx-top)*q/(layers-1); }
        // EX2 ANIM a=1: retain -4*velocity displacement; omit birth phase.
        _ = fire(TH15_BIG_BALL, 2, $self_x, $self_y-4*speed,
                 speed, 90deg, none, none);
    }
}

async sub phantom() {
    set_invuln(65535);
    // st06:1049-1050: source diameters 28/16 -> radii 14/8.
    set_hurtbox(14fx);
    set_hitbox(8fx);
    var cx: fx = $self_x;
    var cy: fx = $self_y;
    // st06:1055-1056: REL circle, independent random phase, omega=2deg/tick,
    // radius linearly 0->16 in 180 ticks, then fixed. ABS stays at birth.
    var phase: int = rand(65536);
    for t in 0..260 {
        var k: int = t+1;
        var radius: fx = 16fx;
        if k < 180 { radius = 16fx*k/180; }
        var theta: angle = (phase+(k*65536)/180) as angle;
        var nx: fx = cx+radius*cos(theta);
        var ny: fx = cy+radius*sin(theta);
        // Predict next source movement tick; target integration precedes next ECL.
        move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
        wait(1);
    }
    // Authorized synthetic death at age260 (wait80+180), immediately before
    // st06:1059 exit. Exactly one callback; death cancels original exit motion.
    death_shot();
    die();
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Entry source frame0 includes its own wait120 (st06:572).
    wait(120);
    var x: fx = -160fx;
    for wave in 0..3 {
        for i in 0..32 {
            // st06:578/588/598: separate x then y RANDF2 samples, no mirror.
            var rx: fx = (rand(65536)-32768) as fx / 32768;
            var ry: fx = (rand(65536)-32768) as fx / 32768;
            _ = spawn_enemy(x+16fx*rx, 128fx+32fx*ry, 170, 0, 0, 0, phantom);
            if wave == 1 { x = x-10fx; } else { x = x+10fx; }
            wait(3);
        }
        // Source carries A through -160 -> 160 -> -160 -> 160.
        if wave < 2 { wait(180); }
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
